<?php
namespace App\Http\Controllers\Website;use App\Http\Controllers\Controller;use App\Http\Requests\Website\UpdateSettingsRequest;use App\Models\{LandingAchievement,LandingFacility,LandingNews,LandingPageSetting,LandingProgram,LandingTestimonial};use App\Services\Website\{LandingPageService,MediaService};use Illuminate\Support\Facades\DB;
class WebsiteAdminController extends Controller {public function index(){return view('website.admin.index',['settings'=>LandingPageSetting::values(),'counts'=>['program'=>LandingProgram::count(),'facility'=>LandingFacility::count(),'achievement'=>LandingAchievement::count(),'published'=>LandingNews::published()->count(),'draft'=>LandingNews::where('status','draft')->count(),'testimonial'=>LandingTestimonial::active()->count()]]);}public function settings(){return view('website.admin.settings',['settings'=>LandingPageSetting::values(),'group'=>request('group','hero')]);}public function update(UpdateSettingsRequest $r,MediaService $media){DB::transaction(function()use($r,$media){foreach($r->input('values',[]) as $key=>$value)LandingPageSetting::updateOrCreate(['key'=>$key],['value'=>$value,'group'=>$r->string('group')]);foreach(['hero_image','about_image','ppdb_image','og_image'] as $key)if($r->hasFile($key)){ $old=LandingPageSetting::where('key',$key)->value('value');LandingPageSetting::updateOrCreate(['key'=>$key],['value'=>$media->replace($r->file($key),$old,$r->string('group')),'type'=>'image','group'=>$r->string('group')]);}});return back()->with('status','Pengaturan website berhasil disimpan.');}public function preview(LandingPageService $service){return view('website.public.home',$service->data(true));}}
